  if($('#issueInvoice'))$('#issueInvoice').onclick=async e=>{const b=e.target;if(window.InvoqlySetup&&!await window.InvoqlySetup.confirmIssue(invoices.find(i=>i.id===b.dataset.id)))return;b.disabled=true;try{await window.InvoqlyInvoiceEmails?.persist(api,b.dataset.id,window.InvoqlyInvoiceEmails.read(),invoices.find(i=>i.id===b.dataset.id));await result(api.rpc('issue_invoice',{p_invoice_id:b.dataset.id}));await load();render();notify(('Invoice issued. Eligible invoice emails are queued for delivery. You can also copy the client link or save a PDF.'));}catch(err){notify(err.message,true);b.disabled=false;}};
